  ((select id from s), 'entrenadores', '[{"id":"c1","nombre":"Coach Diego","sede":"manchay","especialidad":"Fuerza e hipertrofia","mensaje":"Te armo la rutina y te acompaño hasta que la técnica salga perfecta.","bio":"Más de 6 años entrenando a personas que empiezan desde cero y a atletas que buscan su mejor marca. Su enfoque: técnica primero, progreso constante.","logros":["Certificado en entrenamiento de fuerza","+300 alumnos acompañados"],"foto":"img/coach.jpg","pos":"70% 30%","fotos":["img/interior.jpg","img/grip.jpg"],"video":"","ig":""},{"id":"c2","nombre":"Coach Andrea","sede":"manchay","especialidad":"Funcional y baile","mensaje":"Entrenar también puede ser divertido. Ven con energía.","bio":"Dirige las clases de funcional y baile. Cree que la constancia nace cuando disfrutas lo que haces.","logros":["Instructora de baile fitness","Especialista en entrenamiento funcional"],"foto":"img/atleta.jpg","pos":"50% 25%","fotos":["img/clase.jpg"],"video":"","ig":""},{"id":"c3","nombre":"Coach Luis","sede":"vmt","especialidad":"Pérdida de grasa","mensaje":"Tu objetivo es mi objetivo: rutina + nutrición, sin excusas.","bio":"Combina entrenamiento y asesoría nutricional para que bajes tu porcentaje de grasa sin perder fuerza.","logros":["Asesor nutricional deportivo"],"foto":"img/hero.jpg","pos":"62% 20%","fotos":[],"video":"","ig":""},{"id":"c4","nombre":"Coach Mía","sede":"vmt","especialidad":"Cardio y acondicionamiento","mensaje":"Paso a paso, cada día un poco más fuerte.","bio":"Te ayuda a ganar resistencia y energía con planes de cardio que se adaptan a tu nivel.","logros":["Especialista en acondicionamiento físico"],"foto":"img/clase.jpg","pos":"42% 35%","fotos":[],"video":"","ig":""}]'::jsonb),
